import type { Alignment, Element, MagicAbility, MoveType, Stats, Trajectory, UnitKind } from '../types';

// The 28 Summons, generated by the Summon generator (rules/summongen.ts,
// scripts/summons.run.ts) and kept here as fixed data. Each one keeps its
// slot's sprite, whose key is its id: the sprite's look sets its Move Types,
// and its Element and Cost come from the agreed slots (multiples of 8 in
// 16..96, unique within an Element; Upkeep is Cost / 8). Per Element: 3
// aligned (Fire and Earth 2 Day + 1 Night, Water and Air 1 Day + 2 Night)
// and 4 unaligned; 18 of the 28 have a Magic Ability. Names are at most 6
// letters. The comment after each row names the reference it was built
// from and the Cost the model gives it.

type Spell = Omit<Extract<MagicAbility, { kind: 'damage' | 'heal' }>, 'id'>;

type Def = [
  id: string,
  name: string,
  element: Element,
  cost: number,
  alignment: Alignment,
  role: string,
  stats: [atk: number, def: number, mp: number, mdf: number, spd: number, mov: number],
  moveTypes: MoveType[],
  attack: [range: number, trajectory?: Trajectory],
  /** null: no Magic Ability. */
  magic: Spell | null,
];

